-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(19, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(2000)  NOT NULL DEFAULT '',
    created_by VARCHAR(200)   NOT NULL,
    created_at TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** A steward re-dates an OPEN or PENDING claim ({@code date}, yyyy-MM-dd). Its due-by stays as it was
 *  fixed and a figure a statement bound it to stays bound, so its period (the one its due-by falls in)
 *  and its number stay too. Refused for anyone else, for any other status, for a claim due by a day
 *  in a closed period, and for a date that is not a date or is after its person's retirement. */
public class RedateClaim {
    public void redate(@RequestParam(name = "by", required = false) String by,
            @RequestParam(name = "date", required = false) String date, @Val Claim claim,
            PersonRepository people, RoleRepository roles, PeriodRepository periods, Out<Redating> redating) throws ClaimStatusException, InvalidClaimException, PeriodClosedException {
        String sheetId = claim.getSheetId();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, by == null ? "" : by))) {
            throw new ClaimStatusException("Only a steward can re-date a claim");
        }
        if (!ClaimStatus.isOpen(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be re-dated");
        }
        LocalDate to;
        try {
            to = LocalDate.parse(date == null ? "" : date.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Not a date: " + date);
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        Person person = people.find(sheetId, claim.getPersonId());
        if (person != null && person.retiredBefore(to)) {
            throw new InvalidClaimException("A claim cannot be dated after its person's retirement");
        }
        String old = claim.getDate();
        claim.setDate(to.toString());
        redating.set(new Redating(old, claim.getDate()));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

public class AddClaim {
    public void add(@RequestParam(name = "by", required = false) String by,
            @Val ValidClaim request, @Val Person person,
            ClaimRepository claims, PeriodRepository periods, SettingRepository settings,
            HolidayRepository holidays, Out<Claim> claim)
            throws PeriodClosedException, InvalidClaimException {
        String user = by == null ? "" : by;
        LocalDate date = request.date() != null ? request.date() : settings.entryDate(person.getSheetId());
        if (person.retiredBefore(date)) {
            throw new InvalidClaimException("The person is retired from " + person.getRetiredFrom());
        }
        // The due-by is fixed now: the person's own terms, else their grade's, else the sheet's, as they stood on its date,
        // moved past the sheet's holidays as they are now.
        // The claim belongs to the period its due-by falls in.
        LocalDate dueBy = holidays.dueBy(person.getSheetId(),
                date.plusDays(settings.terms(person.getSheetId(), person, date.toString())));
        periods.requireOpen(person.getSheetId(), dueBy.toString());
        String corrects = Corrections.check(request, person.getSheetId(), person.getId(), claims);
        Claim added = claims.add(person.getSheetId(), person.getId(), request.amount(), date,
                request.note(), corrects, dueBy, user);
        if (periods.softClosedOn(person.getSheetId(), dueBy.toString())) claims.markLateEntry(added);
        claim.set(added);
    }
}
 *  now from the terms in force on its date (moved past the sheet's holidays), is split from its number (a late entry when its due-by
 *  falls in a soft-closed period). The split is judged by the original claim alone: refused for a claim
 *  due by a day in a closed period, one not OPEN or deferred, a role that may not open a claim, and an amount that is
 *  not more than 0.00 and less than the claim's (two decimals at most). */
public class SplitClaim {
    public void split(@RequestParam(name = "by", required = false) String by,
            @RequestParam(name = "amount", required = false) String amount, @Val Claim claim,
            ClaimRepository claims, PeriodRepository periods, SettingRepository settings,
            SheetRepository sheets, RoleRepository roles, PersonRepository people, HolidayRepository holidays,
            Out<Split> split)
            throws ClaimStatusException, InvalidClaimException, PeriodClosedException {
        String sheetId = claim.getSheetId();
        periods.requireOpen(sheetId, claim.getDueBy());
        if (!ClaimStatus.OPEN.name().equals(claim.getStatus()) || claim.isDeferred()) {
            throw new ClaimStatusException("A " + (claim.isDeferred() ? "deferred" : claim.getStatus())
                    + " claim cannot be split");
        }
        if (!Permissions.allows(sheetId, by, Permissions.OPEN, roles, settings)) {
            throw new ClaimStatusException("Your role may not open a claim");
        }
        BigDecimal part;
        try {
            part = new BigDecimal(amount == null ? "" : amount.trim());
        } catch (NumberFormatException e) {
            throw new InvalidClaimException("Not an amount: " + amount);
        }
        BigDecimal whole = new BigDecimal(claim.getAmount());
        if (part.scale() > 2 || part.signum() <= 0 || part.compareTo(whole) >= 0) {
            throw new InvalidClaimException("A split needs an amount more than 0.00 and less than " + claim.getAmount());
        }
        claim.setAmount(whole.subtract(part).setScale(2).toPlainString());
        claim.bind(false, null);

        String user = by == null ? "" : by;
        LocalDate date = LocalDate.parse(claim.getDate());
        Person person = people.find(sheetId, claim.getPersonId());
        LocalDate dueBy = holidays.dueBy(sheetId, date.plusDays(settings.terms(sheetId, person, claim.getDate())));
        Claim created = claims.add(sheetId, claim.getPersonId(), part.setScale(2), date, claim.getNote(),
                null, dueBy, user);
        if (periods.softClosedOn(sheetId, created.getDueBy())) claims.markLateEntry(created);
        created.setStatus(ClaimStatus.OPEN.name());
        created.setNumber(ClaimNumbers.next(created, claims, periods, settings, sheets));
        created.setOpenedBy(user);
        created.setSplitFrom(claim.getNumber());
        split.set(new Split(claim, created));
    }
}

